  liu("I play volleyball on Sundays.", "Прослухайте. Коли людина грає у волейбол?", ["По неділях", "По суботах", "По п'ятницях"], "Sundays."),
  liu("My father plays golf.", "Прослухайте. У що грає тато?", ["У гольф", "У теніс", "У футбол"], "Golf."),
  liu("We go skating in winter.", "Прослухайте. Коли вони катаються?", ["Узимку", "Улітку", "Восени"], "Winter."),
  fb("I ___ volleyball on Sundays.", ["play", "go", "do"], "Play volleyball."),
  fb("We ___ skating in winter.", ["go", "play", "make"], "Go skating."),
  fb("He ___ boxing twice a week.", ["does", "plays", "goes"], "Does boxing."),
